import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)

UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
PROCESSOR_BIN = os.environ.get('PROCESSOR_BIN', '/usr/local/bin/imgprocess')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'webp'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def load_processing_config():
    config_path = os.environ.get('PROCESSING_CONFIG', '/etc/imgproc/config.yaml')
    try:
        with open(config_path, 'r') as f:
            return yaml.safe_load(f)
    except FileNotFoundError:
        return {'quality': 85, 'max_dimension': 2048}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_dimensions(width, height, config):
    max_dim = config.get('max_dimension', 2048)
    if width > max_dim or height > max_dim:
        return False
    return True

@app.route('/api/v2/process', methods=['POST'])
def process_image():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    # Read processing parameters from request
    output_format = request.form.get('format', 'png')
    width = request.form.get('width', '800')
    height = request.form.get('height', '600')
    extra_args = request.form.get('args', '')

    config = load_processing_config()

    try:
        w, h = int(width), int(height)
    except ValueError:
        return jsonify({'error': 'Invalid dimensions'}), 400

    if not validate_dimensions(w, h, config):
        return jsonify({'error': 'Dimensions exceed maximum'}), 400

    # Save uploaded file
    filename = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    # Build processing command
    output_filename = f"processed_{os.path.splitext(filename)[0]}.{output_format}"
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Construct command with user-supplied parameters
    cmd = f"{PROCESSOR_BIN} -i {input_path} -o {output_path} -w {width} -h {height} -f {output_format}"

    if extra_args:
        # Allow power users to pass additional processor flags
        cmd += f" {extra_args}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            app.logger.error(f"Processing failed: {result.stderr.decode()}")
            return jsonify({'error': 'Processing failed'}), 500

        return jsonify({
            'status': 'success',
            'output': output_filename,
            'size': os.path.getsize(output_path)
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Processing timeout'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/v2/batch', methods=['POST'])
def batch_process():
    """Process multiple images with a shared configuration"""
    if not request.is_json:
        return jsonify({'error': 'JSON body required'}), 400

    batch_config = request.get_json()
    jobs = batch_config.get('jobs', [])

    if len(jobs) > 20:
        return jsonify({'error': 'Maximum 20 jobs per batch'}), 400

    results = []
    for job in jobs:
        # Each job references a previously uploaded file
        source = secure_filename(job.get('source', ''))
        source_path = os.path.join(UPLOAD_DIR, source)
        if not os.path.exists(source_path):
            results.append({'source': source, 'error': 'not found'})
            continue
        results.append({'source': source, 'status': 'queued'})

    return jsonify({'batch_id': os.urandom(8).hex(), 'results': results})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
